try:
 import pyBigWig; print(pyBigWig.__version__,pyBigWig.remote)
except Exception as e: print(type(e).__name__,e)
PY
python - <<'PY'
import json,collections
J=json.load(open('encode_alignment_files.json'))['@graph']
G=collections.defaultdict(list)
for f in J:
 if any(a.get('title')=='ENCODE4 v3.0.0-alpha.2 GRCh38' for a in f.get('analyses',[])):
  t=next((q.get('total') for q in f.get('quality_metrics',[]) if 'SamtoolsFlagstatsQualityMetric' in q.get('@type',[])),None)
  G[f['dataset'].split('/')[-2]].append((f['accession'],t,f['file_size']))
target=76275859
pl=[]
for ex,v in G.items():
 s=sum(x[1] for x in v)
 if target<=s<=110_000_000:pl.append((s,ex,v))
print('plausible',len(pl))
for x in sorted(pl):print(x)
PY"

