/bin/bash -lc "python - <<'PY'
import gzip,numpy as np,pyBigWig,time
v=[]
for l in gzip.open('reverse.encode.q1.tsv.gz','rt'):
 a=l.split();
 if a[0]=='chr1' and int(a[1])<10_000_000:v.append(float(a[3]))
u='https://encode-public.s3.amazonaws.com/2020/11/12/31cec132-6555-4b4e-a906-18ba1b587b94/ENCFF389PZY.bigWig'
for exact in [False,True]:
 t=time.time(); b=pyBigWig.open(u); x=np.array(b.stats('chr1',0,10_000_000,nBins=1000,type='mean',exact=exact)); b.close(); print(exact,'time',time.time()-t,'corr',np.corrcoef(v,np.nan_to_num(x))[0,1], 'max',x.max())
PY"
